export const grammarGroupNames = {classes:'Части речи',functions:'Члены предложения',morphology:'Морфологические категории',units:'Синтаксические единицы',semantics:'Семантические роли',discourse:'Организация высказывания',functional:'Функциональные категории'};
export const grammarUi={meaning:'Meaning',structure:'Structure and use',distinctions:'Distinctions and common mistakes',examples:'Examples',vocabulary:'Grammar vocabulary',references:'References'};
const note = (ru,en,definition,pattern,patternRu,contrast,contrastRu,examples) => ({ru,en,definition,pattern,patternRu,contrast,contrastRu,examples:examples.split('|').map(line=>line.split('~'))});
export const grammarDetails = {
  Noun:note('Существительное','A noun identifies an entity, substance, quality or idea. Its grammatical behaviour matters more than whether it names a physical thing.','Существительное обозначает участника, вещество, качество или понятие. Его класс определяется и грамматическим поведением, а не только значением.',
    'Common/proper; countable/uncountable; concrete/abstract. A noun can head a subject, object or complement phrase.','Нарицательные/собственные; исчисляемые/неисчисляемые; конкретные/абстрактные. Именная группа может быть подлежащим, дополнением или комплементом.',
    'A noun is a word class; a subject is a function. Do not use a/an with uncountable information.','Существительное — часть речи, подлежащее — функция. Перед неисчисляемым information не ставится a/an.',
    'A visitor arrived.~Пришёл посетитель.|Maya lives in Leeds.~Майя живёт в Лидсе.|We need fresh water.~Нам нужна свежая вода.|Their kindness surprised me.~Их доброта меня удивила.|Two children were laughing.~Двое детей смеялись.|She gave me useful information.~Она дала мне полезную информацию.'),
  Verb:note('Глагол','A verb heads a verb phrase and expresses an action, event or state. Auxiliary verbs help build questions, negation, aspect and voice.','Глагол возглавляет глагольную группу и выражает действие, событие или состояние. Вспомогательные глаголы участвуют в вопросах, отрицании, виде и залоге.',
    'Lexical/auxiliary; transitive/intransitive; finite/non-finite. A finite verb normally agrees with its subject in the present simple.','Смысловые/вспомогательные; переходные/непереходные; личные/неличные формы. В present simple личная форма обычно согласуется с подлежащим.',
    'A verb is not always an action: know and belong describe states. After did, use the base form, not a past form.','Глагол не обязательно обозначает действие: know и belong выражают состояния. После did нужна начальная, а не прошедшая форма.',
    'The baby smiled.~Малыш улыбнулся.|I know the answer.~Я знаю ответ.|She has finished.~Она закончила.|Did they arrive?~Они приехали?|He does not drive.~Он не водит машину.|The parcel was delivered.~Посылку доставили.'),
  Adjective:note('Прилагательное','An adjective describes or classifies a noun phrase. Many adjectives can occur before a noun or after a linking verb.','Прилагательное описывает или классифицирует именную группу. Многие прилагательные употребляются перед существительным и после глагола-связки.',
    'Attributive: a quiet room. Predicative: the room is quiet. Gradable adjectives allow very and comparison; not all adjectives are gradable.','Перед существительным: a quiet room. В составе сказуемого: the room is quiet. Градуируемые признаки допускают very и сравнение, но не все прилагательные таковы.',
    'Adjectives do not normally take plural -s. Compare a careful driver with drive carefully.','Прилагательные обычно не получают множественное -s. Различайте a careful driver и drive carefully.',
    'We found a quiet café.~Мы нашли тихое кафе.|The café is quiet.~В кафе тихо.|These bags are heavy.~Эти сумки тяжёлые.|She seems tired.~Она кажется уставшей.|This route is shorter.~Этот маршрут короче.|It was a wooden bridge.~Это был деревянный мост.'),
  Adverb:note('Наречие','An adverb can modify a verb, adjective, another adverb or a whole clause. It can express manner, time, frequency or the speaker’s attitude.','Наречие может уточнять глагол, прилагательное, другое наречие или всё предложение. Оно выражает образ действия, время, частотность или оценку говорящего.',
    'Manner: gently; frequency: often; degree: quite; time: yesterday; stance: fortunately. Position depends on meaning and scope.','Образ действия: gently; частотность: often; степень: quite; время: yesterday; оценка: fortunately. Позиция зависит от значения и области действия.',
    'Not every adverb ends in -ly: fast and well are adverbs. Friendly is usually an adjective.','Не каждое наречие заканчивается на -ly: fast и well — наречия. Friendly обычно является прилагательным.',
    'Please speak clearly.~Пожалуйста, говорите ясно.|She often walks here.~Она часто здесь гуляет.|It is quite cold.~Довольно холодно.|He ran very quickly.~Он бежал очень быстро.|We met yesterday.~Мы встретились вчера.|Fortunately, nobody fell.~К счастью, никто не упал.'),
  Pronoun:note('Местоимение','A pronoun refers to a participant or stands in place of a noun phrase whose reference comes from context.','Местоимение указывает на участника или заменяет именную группу, значение которой понятно из контекста.',
    'Personal: I/me; possessive: mine; reflexive: myself; demonstrative: this; indefinite: someone; relative: who. Choose subject or object form by function.','Личные: I/me; притяжательные: mine; возвратные: myself; указательные: this; неопределённые: someone; относительные: who. Форму выбирают по функции.',
    'My before a noun is a possessive determiner; mine can stand alone. Between you and me uses object forms.','My перед существительным — притяжательный определитель; mine употребляется самостоятельно. В between you and me нужны объектные формы.',
    'She knows us.~Она нас знает.|This is mine.~Это моё.|I hurt myself.~Я ушибся.|Someone is waiting.~Кто-то ждёт.|Those are expensive.~Те вещи дорогие.|The person who called left a message.~Человек, который звонил, оставил сообщение.'),
  Determiner:note('Определитель','A determiner helps specify the reference or quantity of a noun phrase. It normally precedes adjectives and the head noun.','Определитель уточняет, о каком предмете или количестве идёт речь. Он обычно стоит перед прилагательными и главным существительным.',
    'Articles: a/the; demonstratives: this/those; possessives: my/our; quantifiers: some/each. Singular count nouns usually need a determiner.','Артикли: a/the; указательные: this/those; притяжательные: my/our; квантификаторы: some/each. Единственное исчисляемое существительное обычно требует определителя.',
    'Do not combine the and my before the same noun: my coat, not the my coat. Terminology varies between grammar traditions.','Не сочетайте the и my перед одним существительным: my coat, не the my coat. Названия классов в разных грамматиках могут отличаться.',
    'A train is coming.~Приближается поезд.|The train is late.~Этот поезд опаздывает.|These tickets are ours.~Эти билеты наши.|My new coat is blue.~Моё новое пальто синее.|Some water spilled.~Немного воды пролилось.|Each student has a key.~У каждого ученика есть ключ.'),
  Preposition:note('Предлог','A preposition heads a prepositional phrase and expresses a relationship such as place, time or connection.','Предлог возглавляет предложную группу и выражает отношение места, времени или другую связь.',
    'Place: under the bed; time: after lunch; direction: towards town. A following pronoun normally has the object form.','Место: under the bed; время: after lunch; направление: towards town. Следующее за предлогом местоимение обычно имеет объектную форму.',
    'A preposition may be followed by an -ing form: interested in learning. A phrasal-verb particle is not always a preposition.','После предлога возможна форма -ing: interested in learning. Частица фразового глагола не всегда является предлогом.',
    'The cat is under the chair.~Кошка под стулом.|We left after lunch.~Мы ушли после обеда.|Walk towards the river.~Идите к реке.|This gift is for her.~Этот подарок для неё.|I am interested in painting.~Я интересуюсь живописью.|They spoke about the journey.~Они говорили о поездке.'),
  Conjunction:note('Союз','A conjunction links units such as words, phrases or clauses. The relationship can be coordination or subordination.','Союз связывает слова, группы слов или части предложения. Связь может быть сочинительной или подчинительной.',
    'Coordinating: and, but, or. Subordinating: because, although, if. Some linking expressions are adverbs rather than conjunctions.','Сочинительные: and, but, or. Подчинительные: because, although, if. Некоторые средства связи относятся к наречиям, а не союзам.',
    'Because introduces a clause; because of normally introduces a noun phrase. However cannot always replace but with the same punctuation.','Because вводит часть предложения, because of обычно вводит именную группу. However нельзя всегда подставлять вместо but с той же пунктуацией.',
    'Tea and coffee are available.~Есть чай и кофе.|It is small but comfortable.~Оно маленькое, но удобное.|Call or send a message.~Позвони или отправь сообщение.|We stayed because it snowed.~Мы остались, потому что шёл снег.|Although tired, she continued.~Хотя она устала, она продолжила.|If you agree, we can begin.~Если ты согласен, мы можем начать.'),
  Interjection:note('Междометие','An interjection is a relatively independent expression of reaction, feeling or attention. Its force depends on intonation and context.','Междометие — относительно самостоятельное выражение реакции, чувства или привлечения внимания. Значение зависит от интонации и контекста.',
    'Surprise: oh/wow; hesitation: um; pain: ouch; attention: hey. It can form an utterance without a subject and verb.','Удивление: oh/wow; заминка: um; боль: ouch; внимание: hey. Междометие может быть самостоятельной репликой без подлежащего и глагола.',
    'An exclamation mark alone does not make a word an interjection. Many interjections are informal.','Восклицательный знак сам по себе не делает слово междометием. Многие междометия разговорные.',
    'Oh, I recognise you.~О, я тебя узнаю.|Wow, that is enormous!~Ого, это огромное!|Ouch, that hurt!~Ой, больно!|Hey, wait for us!~Эй, подождите нас!|Um, let me think.~Эм, дай подумать.|Hooray, we finished!~Ура, мы закончили!'),
  Numeral:note('Числительное','A numeral expresses a number or numerical order. Grammars differ in whether numerals form a separate word class or a determiner subclass.','Числительное выражает число или порядок. В разных грамматиках числительные рассматриваются как отдельный класс или разновидность определителей.',
    'Cardinal: three; ordinal: third; fractions: a third. Number words can occur before nouns or independently.','Количественные: three; порядковые: third; дроби: a third. Числительные употребляются перед существительными и самостоятельно.',
    'After a precise number use hundred, not hundreds: two hundred. Ordinals usually take the in a specific sequence.','После точного числа используется hundred, не hundreds: two hundred. При указании места в конкретном ряду порядковое обычно имеет the.',
    'Three buses stopped.~Остановились три автобуса.|I chose the third option.~Я выбрал третий вариант.|Two hundred people came.~Пришли двести человек.|Half the cake is left.~Осталась половина торта.|We need a quarter of a litre.~Нам нужна четверть литра.|Seven is a prime number.~Семь — простое число.')
};
const add = (title,...fields) => { grammarDetails[title]=note(...fields); };
add('Subject','Подлежащее','The subject is a grammatical function, usually controlling agreement and preceding the finite verb in an ordinary statement.','Подлежащее — грамматическая функция: оно обычно определяет согласование и предшествует личному глаголу в обычном утверждении.',
  'Noun phrases, pronouns, -ing clauses and infinitive clauses can be subjects. In a yes/no question, an auxiliary usually moves before the subject.','Подлежащим могут быть именные группы, местоимения, герундиальные и инфинитивные конструкции. В общем вопросе вспомогательный глагол обычно стоит перед подлежащим.',
  'Subject does not mean doer: in a passive clause the affected participant can be the subject. Imperatives often leave you unspoken.','Подлежащее не обязательно деятель: в пассиве им может быть участник, испытывающий воздействие. В побуждении you часто не выражено.',
  'The gardener opened the gate.~Садовник открыл калитку.|The gate was opened.~Калитку открыли.|She is waiting.~Она ждёт.|Swimming keeps me fit.~Плавание помогает мне быть в форме.|Is your brother ready?~Твой брат готов?|It is raining.~Идёт дождь.');
add('Predicate','Сказуемое','In a broad traditional analysis, the predicate says something about the subject and includes the verb with its dependent elements.','В широком традиционном понимании сказуемое сообщает что-либо о подлежащем и включает глагол с зависимыми компонентами.',
  'A predicate may contain only a verb, or a verb with objects, complements and adjuncts. Some school grammars use a narrower meaning.','Сказуемое может состоять только из глагола или включать дополнения, комплементы и обстоятельства. В некоторых учебных традициях термин понимается уже.',
  'Do not confuse the whole predicate with its head verb. The analysis reads a book contains more than the word reads.','Не путайте целое сказуемое с главным глаголом. В анализе reads a book сказуемое шире одного reads.',
  'The audience laughed.~Зрители засмеялись.|Mira reads a newspaper.~Мира читает газету.|The soup smells wonderful.~Суп замечательно пахнет.|Our neighbours have moved away.~Наши соседи переехали.|The child gave me a drawing.~Ребёнок подарил мне рисунок.|The letter was delivered yesterday.~Письмо доставили вчера.');
add('Direct Object','Прямое дополнение','A direct object is a complement selected by a transitive verb. It often denotes an affected entity, but meaning alone is not a reliable test.','Прямое дополнение — компонент, который допускается переходным глаголом. Часто это объект воздействия, но одного значения для определения недостаточно.',
  'Typical order: subject + verb + object. Objects can be noun phrases, pronouns or clauses. Object pronouns include me, him, her and them.','Обычный порядок: подлежащее + глагол + дополнение. Дополнением могут быть именные группы, местоимения или придаточные. Объектные формы: me, him, her, them.',
  'A linking verb takes a subject complement, not a direct object: She became a doctor. Not every direct object readily becomes a passive subject.','После глагола-связки стоит комплемент подлежащего, не прямое дополнение: She became a doctor. Не всякое прямое дополнение легко преобразуется в подлежащее пассива.',
  'I opened the window.~Я открыл окно.|She knows him.~Она его знает.|We enjoyed the concert.~Нам понравился концерт.|They built a bridge.~Они построили мост.|I believe that she is right.~Я считаю, что она права.|Please bring your passport.~Пожалуйста, принесите паспорт.');
add('Indirect Object','Косвенное дополнение','An indirect object occurs in a double-object construction and often identifies a recipient or beneficiary.','Косвенное дополнение встречается в конструкции с двумя дополнениями и часто обозначает получателя или выгодополучателя.',
  'Subject + verb + indirect object + direct object: I sent her a photo. A related prepositional pattern may use to or for.','Подлежащее + глагол + косвенное дополнение + прямое: I sent her a photo. В близкой предложной конструкции возможны to или for.',
  'Not every verb allows both patterns: explain the rule to me, not explain me the rule. Some grammars distinguish a to-phrase from an indirect object.','Не каждый глагол допускает обе конструкции: explain the rule to me, не explain me the rule. Некоторые грамматики отличают группу с to от косвенного дополнения.',
  'She gave me a map.~Она дала мне карту.|He sent his aunt a letter.~Он отправил тёте письмо.|We bought the children presents.~Мы купили детям подарки.|Tell us the story.~Расскажи нам эту историю.|I offered Anna a seat.~Я предложил Анне место.|They showed the visitors the garden.~Они показали посетителям сад.');
add('Complement','Комплемент','A complement is licensed by a head and completes its grammatical or semantic pattern. The term covers several constructions, depending on the grammar.','Комплемент допускается главным словом и дополняет его грамматическую или смысловую модель. Объём термина зависит от грамматической традиции.',
  'Subject complement: she is tired. Object complement: they painted it blue. Other complements can follow nouns, adjectives or prepositions.','Комплемент подлежащего: she is tired. Объектный комплемент: they painted it blue. Другие комплементы бывают при существительных, прилагательных и предлогах.',
  'A complement is not simply any optional detail. Compare put the bag on the shelf, where the location completes put, with sleep on the sofa.','Комплемент — не любая дополнительная подробность. В put the bag on the shelf место завершает модель put, в sleep on the sofa оно скорее дополнительное.',
  'He became a pilot.~Он стал пилотом.|The room looks clean.~Комната выглядит чистой.|They elected her chairperson.~Её избрали председателем.|We painted the door green.~Мы покрасили дверь в зелёный.|I am afraid of heights.~Я боюсь высоты.|Put the parcel on the desk.~Положи посылку на стол.');
add('Adverbial / Adjunct','Обстоятельство / адъюнкт','An adjunct adds information such as time, place, manner, reason or viewpoint without being selected as a core complement.','Адъюнкт добавляет время, место, способ, причину или точку зрения, не будучи основным комплементом, требуемым главным словом.',
  'An adjunct can be an adverb, prepositional phrase, noun phrase or clause. Several adjuncts can occur in one clause.','Адъюнкт может быть наречием, предложной или именной группой, придаточной частью. В предложении возможны несколько обстоятельств.',
  'Adverb names a word class; adverbial names a function. A required location may be a complement rather than an adjunct.','Adverb — часть речи, adverbial — функция. Обязательное указание места может быть комплементом, а не адъюнктом.',
  'We met outside.~Мы встретились снаружи.|She arrived on Tuesday.~Она приехала во вторник.|He answered with confidence.~Он ответил уверенно.|I stayed because I was tired.~Я остался, потому что устал.|They walked home in silence.~Они молча пошли домой.|Fortunately, the train waited.~К счастью, поезд подождал.');
add('Attribute / Modifier','Определение / модификатор','A modifier narrows or enriches the interpretation of another expression. Attribute is a traditional term often used for a modifier of a noun.','Модификатор уточняет значение другого выражения. Определением в традиционной терминологии часто называют модификатор существительного.',
  'Premodifiers precede the head; postmodifiers follow it. Adjectives, nouns, phrases and relative clauses can modify a noun phrase.','Премодификаторы стоят перед главным словом, постмодификаторы — после него. Именную группу могут уточнять прилагательные, существительные, группы и относительные придаточные.',
  'A modifier need not be an adjective. In a stone wall, stone is a noun used as a modifier.','Модификатор не обязательно прилагательное. В a stone wall слово stone является существительным в функции модификатора.',
  'A red kite flew above us.~Над нами летел красный воздушный змей.|I bought a coffee cup.~Я купил кофейную чашку.|The house by the lake is empty.~Дом у озера пуст.|The woman who waved is my aunt.~Женщина, которая помахала, — моя тётя.|It was a very unusual answer.~Это был очень необычный ответ.|We need something useful.~Нам нужно что-нибудь полезное.');
add('Number','Число','Grammatical number distinguishes singular and plural forms and participates in agreement. Not every noun has a regular countable plural.','Грамматическое число различает единственное и множественное и участвует в согласовании. Не у каждого существительного есть обычное исчисляемое множественное.',
  'Regular plurals use -s/-es; irregular ones include children and mice. Some forms are unchanged. Uncountable nouns normally take singular agreement.','Обычное множественное образуется с -s/-es; неправильные формы: children, mice. Некоторые формы не меняются. Неисчисляемые обычно согласуются в единственном.',
  'Advice and furniture are normally uncountable: some advice, not advices. Collective-noun agreement can differ between British and American usage.','Advice и furniture обычно неисчисляемы: some advice, не advices. Согласование собирательных может отличаться в британском и американском вариантах.',
  'One leaf fell.~Упал один лист.|Several leaves fell.~Упало несколько листьев.|The child is asleep.~Ребёнок спит.|The children are asleep.~Дети спят.|Two sheep crossed the road.~Две овцы перешли дорогу.|This furniture is new.~Эта мебель новая.');
add('Gender','Род','English has little noun-based grammatical gender. Gender distinctions appear mainly in personal reference and pronoun choice.','В английском почти нет грамматического рода существительных. Различия главным образом проявляются в обозначении людей и выборе местоимений.',
  'He/she can refer to people; it often refers to things or animals when appropriate. Singular they is widely used for unknown or nonbinary personal reference.','He/she обозначают людей; it часто обозначает вещи или животных в подходящем контексте. Единственное they употребляется при неизвестном гендере и для небинарных людей.',
  'An English noun does not inherit the gender of its Russian translation. Use a person’s stated pronouns when known.','Английское существительное не наследует род русского перевода. Если местоимения человека известны, используйте их.',
  'My sister said she would come.~Сестра сказала, что придёт.|My brother said he would help.~Брат сказал, что поможет.|The chair is old, but it is strong.~Стул старый, но прочный.|Someone left their umbrella.~Кто-то оставил свой зонт.|Alex said they were ready.~Алекс сказал, что готов.|The doctor introduced herself.~Врач представилась.');
add('Case','Падеж','Case is a grammatical distinction associated with syntactic relationships. English preserves clear case contrasts mainly in pronouns and possessive marking.','Падеж — грамматическое различие, связанное с синтаксическими отношениями. В английском оно заметно главным образом в местоимениях и притяжательном оформлении.',
  'Subject forms: I/he/she/we/they. Object forms: me/him/her/us/them. Possession: the teacher’s desk; the teachers’ room.','Формы подлежащего: I/he/she/we/they. Объектные: me/him/her/us/them. Принадлежность: the teacher’s desk; the teachers’ room.',
  'After a preposition, normally use an object form: for him. English does not have the full Russian noun-case system.','После предлога обычно нужна объектная форма: for him. У английских существительных нет полной русской падежной системы.',
  'I saw her.~Я увидел её.|She saw me.~Она увидела меня.|This is for him.~Это для него.|We spoke to them.~Мы поговорили с ними.|The teacher’s bag is here.~Сумка учителя здесь.|The students’ books are upstairs.~Книги студентов наверху.');
add('Person','Лицо','Person distinguishes the speaker, the addressee and other referents. In English it affects pronouns and a limited set of verb forms.','Лицо различает говорящего, адресата и остальных участников. В английском оно влияет на местоимения и некоторые глагольные формы.',
  'First person: I/we; second: you; third: he/she/it/they. Present simple lexical verbs normally add -s only in third-person singular.','Первое лицо: I/we; второе: you; третье: he/she/it/they. Смысловой глагол в present simple обычно получает -s только в третьем лице единственного числа.',
  'You can be singular or plural. After does, the lexical verb has no -s: Does she work?','You может быть единственным и множественным. После does смысловой глагол не имеет -s: Does she work?',
  'I work nearby.~Я работаю поблизости.|We work together.~Мы работаем вместе.|You work at home.~Ты работаешь дома.|She works at night.~Она работает ночью.|They work abroad.~Они работают за границей.|Does he work here?~Он здесь работает?');
add('Tense','Грамматическое время','Tense locates a situation relative to a temporal reference point. English distinguishes inflected present and past, while future time has several constructions.','Время соотносит ситуацию с временной точкой отсчёта. В английском различают морфологические настоящее и прошедшее; будущее выражается несколькими конструкциями.',
  'Present: work/works; past: worked. Future reference: will, be going to, present continuous or present simple in appropriate contexts.','Настоящее: work/works; прошедшее: worked. Будущее: will, be going to, present continuous или present simple в соответствующих контекстах.',
  'Classroom tense tables often combine tense and aspect. A present form can refer to future time, and a past form can express politeness or unreality.','Учебные таблицы времён часто объединяют время и аспект. Настоящая форма может обозначать будущее, прошедшая — вежливость или нереальность.',
  'She works here.~Она здесь работает.|She worked here last year.~Она работала здесь в прошлом году.|I will call tomorrow.~Я позвоню завтра.|We are leaving on Friday.~Мы уезжаем в пятницу.|The train leaves at six.~Поезд отправляется в шесть.|I wondered if you could help.~Я хотел спросить, не могли бы вы помочь.');
add('Aspect','Аспект / вид','Aspect presents a situation as ongoing, completed or connected to another reference point. English progressive and perfect constructions are central examples.','Аспект представляет ситуацию как развивающуюся, завершённую или связанную с другой точкой отсчёта. Основные английские примеры — progressive и perfect.',
  'Progressive: be + -ing. Perfect: have + past participle. They can combine: have been working. Simple forms are not progressive or perfect.','Progressive: be + -ing. Perfect: have + причастие прошедшего времени. Они сочетаются: have been working. Simple не является ни progressive, ни perfect.',
  'English aspect does not correspond one-to-one to Russian perfective/imperfective verbs. Perfect describes a relation to a reference time, not simply any finished action.','Английский аспект не совпадает напрямую с русскими совершенным и несовершенным видами. Perfect выражает связь с точкой отсчёта, а не просто любое завершённое действие.',
  'I read every evening.~Я читаю каждый вечер.|I am reading now.~Я сейчас читаю.|I have read the report.~Я уже прочитал отчёт.|I was reading when you called.~Я читал, когда ты позвонил.|I had read it before the meeting.~Я прочитал это до встречи.|I have been reading for an hour.~Я читаю уже час.');
add('Mood','Наклонение','Mood concerns grammatical ways of presenting statements, directives and non-factual possibilities. English mood distinctions are limited and partly constructional.','Наклонение связано с грамматическим оформлением утверждений, побуждений и нереальных возможностей. В английском эти различия ограничены и частично выражаются конструкциями.',
  'Indicative is typical in factual statements; imperative gives directives. Subjunctive uses include mandative be and irrealis were.','Изъявительное типично для утверждений; повелительное выражает побуждение. Сослагательные употребления включают be после требования и were в нереальном условии.',
  'Mood and modality are related but not identical. Can and must express modality without creating a separate inflected mood paradigm.','Наклонение и модальность связаны, но не тождественны. Can и must выражают модальность, не создавая отдельной системы личных окончаний.',
  'She is at home.~Она дома.|Please sit down.~Пожалуйста, садитесь.|Do not touch the wire.~Не трогайте провод.|They insist that he be present.~Они настаивают на его присутствии.|If I were you, I would wait.~На твоём месте я бы подождал.|I wish it were warmer.~Хотелось бы, чтобы было теплее.');
add('Voice','Залог','Voice changes how participants are mapped to grammatical functions. In a passive construction, an object-like participant is presented as the subject.','Залог меняет соответствие участников грамматическим функциям. В пассивной конструкции участник, соответствующий дополнению актива, представлен как подлежащее.',
  'Active: someone repaired the gate. Passive: the gate was repaired. Passive commonly uses be + past participle; a by-phrase can identify the agent.','Актив: someone repaired the gate. Пассив: the gate was repaired. Пассив обычно образуется с be + причастие; группа с by может назвать деятеля.',
  'Not every be + participle is unambiguously passive; some describe a state. Intransitive verbs normally cannot form an ordinary passive.','Не каждое be + причастие однозначно является пассивом: возможно описание состояния. Непереходные глаголы обычно не образуют обычного пассива.',
  'A mechanic repaired the van.~Механик починил фургон.|The van was repaired yesterday.~Фургон починили вчера.|Someone has cancelled the flight.~Кто-то отменил рейс.|The flight has been cancelled.~Рейс отменён.|The forms must be signed.~Бланки должны быть подписаны.|The house is being painted.~Дом сейчас красят.');
add('Degree','Степень сравнения','Degree expresses a scale of a property, including comparative and superlative contrasts. It is typical of gradable adjectives and some adverbs.','Степень сравнения выражает положение признака на шкале, включая сравнительную и превосходную формы. Она характерна для градуируемых прилагательных и ряда наречий.',
  'Short adjectives often use -er/-est; many longer ones use more/most. Equality uses as ... as. Irregular forms include good/better/best.','Короткие прилагательные часто имеют -er/-est; многие длинные — more/most. Равенство: as ... as. Неправильные формы: good/better/best.',
  'Do not combine more with an -er comparative: better, not more better. Not all adjectives allow ordinary comparison.','Не сочетайте more с формой на -er: better, не more better. Не все прилагательные допускают обычное сравнение.',
  'This bag is light.~Эта сумка лёгкая.|That bag is lighter.~Та сумка легче.|This is the lightest bag.~Это самая лёгкая сумка.|The task is more difficult.~Задание сложнее.|She speaks more clearly now.~Сейчас она говорит яснее.|My room is as large as yours.~Моя комната такая же большая, как твоя.');
add('Phrase','Синтаксическая группа','A phrase is a syntactic unit organised around a head. In many analyses a phrase may consist of a single head word, not necessarily several words.','Синтаксическая группа организована вокруг главного компонента. Во многих описаниях она может состоять из одного главного слова, а не обязательно нескольких.',
  'NP: noun phrase; VP: verb phrase; PP: prepositional phrase; AdjP/AP: adjective phrase; AdvP: adverb phrase. Identify the head before classifying the phrase.','NP — именная, VP — глагольная, PP — предложная, AdjP/AP — адъективная, AdvP — наречная группа. Сначала определите главное слово.',
  'Phrase classes and sentence functions are different: a noun phrase may be a subject, object or complement.','Классы групп и функции различаются: именная группа бывает подлежащим, дополнением или комплементом.',
  'The very old tree fell.~Очень старое дерево упало.|She has been waiting.~Она уже некоторое время ждёт.|The keys are under the sofa.~Ключи под диваном.|He looks extremely happy.~Он выглядит чрезвычайно счастливым.|She answered quite confidently.~Она ответила довольно уверенно.|Birds sing.~Птицы поют.');
add('Main Clause','Главная часть предложения','A main clause is not subordinate to another clause. It may form a whole sentence or combine with subordinate or coordinated clauses.','Главная часть не подчинена другой части предложения. Она может образовывать целое предложение или сочетаться с придаточными и сочинёнными частями.',
  'Main clauses can be statements, questions, directives or exclamatives. A sentence may contain more than one coordinated main clause.','Главные части могут быть утверждениями, вопросами, побуждениями или восклицаниями. В предложении возможно несколько сочинённых главных частей.',
  'Do not identify the main clause solely by its position: a subordinate clause can appear first.','Не определяйте главную часть только по позиции: придаточная может стоять в начале.',
  'I waited until the rain stopped.~Я подождал, пока дождь закончился.|When she called, I answered.~Когда она позвонила, я ответил.|The sun set and we went home.~Солнце село, и мы пошли домой.|Do you know where he lives?~Ты знаешь, где он живёт?|Please call me when you arrive.~Пожалуйста, позвони, когда приедешь.|What a surprise it was!~Какой это был сюрприз!');
add('Subordinate Clause','Придаточная часть','A subordinate clause functions within a larger construction, for example as a complement, modifier or adjunct.','Придаточная часть выполняет функцию в более крупной конструкции: например, комплемента, модификатора или обстоятельства.',
  'Content: that she left; relative: who lives nearby; adverbial: because it rained. Clauses can be finite or non-finite.','Изъяснительная: that she left; относительная: who lives nearby; обстоятельственная: because it rained. Придаточные бывают личными и неличными.',
  'Indirect questions normally use statement order: I know where she is, not where is she. A subordinate clause need not start with that.','В косвенных вопросах обычно прямой порядок: I know where she is, не where is she. Придаточная не обязательно начинается с that.',
  'I think that she agreed.~Думаю, она согласилась.|The neighbour who helped is a nurse.~Соседка, которая помогла, — медсестра.|We stayed because it rained.~Мы остались, потому что шёл дождь.|Tell me where you live.~Скажи мне, где ты живёшь.|I want to leave early.~Я хочу уйти пораньше.|Although he was tired, he smiled.~Хотя он устал, он улыбнулся.');
const sentenceWarning=['Sentence form and communicative purpose do not always coincide: a question can be a polite request.','Форма предложения и цель высказывания не всегда совпадают: вопрос может выражать вежливую просьбу.'];
add('Declarative Sentence','Повествовательное предложение','A declarative clause typically presents a statement. Its usual English order places the subject before the finite verb.','Повествовательная конструкция обычно выражает утверждение. В обычном порядке подлежащее предшествует личному глаголу.',
  'Subject + verb (+ complements/adjuncts). Negative declaratives use an auxiliary with not, or another negative expression.','Подлежащее + глагол (+ комплементы/обстоятельства). Отрицание выражается вспомогательным глаголом с not или другим отрицательным средством.',...sentenceWarning,
  'Our bus is late.~Наш автобус опаздывает.|She enjoys science.~Ей нравится наука.|I have never been there.~Я там никогда не был.|Nobody answered.~Никто не ответил.|We do not need a taxi.~Нам не нужно такси.|The museum opens at ten.~Музей открывается в десять.');
add('Interrogative Sentence','Вопросительное предложение','An interrogative clause has a grammatical question form. It can ask for information, confirmation or a choice.','Вопросительная конструкция имеет грамматическую форму вопроса. Она может запрашивать информацию, подтверждение или выбор.',
  'Yes/no: auxiliary + subject + verb. Wh-question: question word + auxiliary + subject + verb. Subject questions often omit do-support.','Общий вопрос: вспомогательный + подлежащее + глагол. Специальный: вопросительное слово + вспомогательный + подлежащее + глагол. Вопрос к подлежащему часто не требует do.',...sentenceWarning,
  'Are they ready?~Они готовы?|Where do you work?~Где ты работаешь?|Who called you?~Кто тебе звонил?|Which route should we take?~Какой маршрут нам выбрать?|Have you seen my keys?~Ты видел мои ключи?|Could you close the door?~Не мог бы ты закрыть дверь?');
add('Imperative Sentence','Побудительное предложение','An imperative clause typically directs, requests, advises or invites someone to act. The understood subject is usually you.','Побудительная конструкция обычно выражает распоряжение, просьбу, совет или приглашение действовать. Подразумеваемое подлежащее обычно you.',
  'Base verb: wait. Negative: do not/don’t + base verb. Let us/let’s is used for proposals involving the speaker.','Начальная форма: wait. Отрицание: do not/don’t + начальная форма. Let us/let’s выражает предложение с участием говорящего.',...sentenceWarning,
  'Please wait here.~Пожалуйста, подождите здесь.|Do not cross the line.~Не переходите черту.|Take a seat.~Присаживайтесь.|Have a good journey.~Хорошей поездки.|Let us begin.~Давайте начнём.|Be careful on the stairs.~Будьте осторожны на лестнице.');
add('Exclamative Sentence','Восклицательная конструкция','An exclamative construction expresses a marked evaluation, often a surprisingly high degree of a property.','Восклицательная конструкция выражает яркую оценку, часто неожиданно высокую степень признака.',
  'What + (a/an) + adjective + noun; how + adjective/adverb. The remaining clause normally keeps statement order.','What + (a/an) + прилагательное + существительное; how + прилагательное/наречие. Далее обычно сохраняется прямой порядок.',
  'Not every sentence ending in ! is an exclamative construction. What a lovely day it is is not a question.','Не каждое предложение с ! является восклицательной конструкцией. What a lovely day it is — не вопрос.',
  'What a wonderful view!~Какой чудесный вид!|How quickly time passes!~Как быстро летит время!|What beautiful flowers!~Какие красивые цветы!|How cold it is today!~Как сегодня холодно!|What an interesting idea!~Какая интересная мысль!|How carefully she works!~Как аккуратно она работает!');
const roleContrast=['Semantic roles describe meaning; subject and object describe syntax. A passive can change syntax while preserving participants’ roles.','Семантические роли описывают значение, подлежащее и дополнение — синтаксис. Пассив меняет синтаксис, сохраняя роли участников.'];
add('Agent','Агенс / деятель','The agent initiates or intentionally carries out an event. Agency can be a matter of degree rather than a simple yes/no property.','Агенс инициирует событие или намеренно выполняет действие. Агентность может быть выражена в разной степени.',
  'Look for the participant acting or controlling the event. It is often the active subject and can appear in a passive by-phrase.','Ищите участника, который действует или контролирует событие. Часто это подлежащее актива или группа с by в пассиве.',...roleContrast,
  'Nora opened the box.~Нора открыла коробку.|The box was opened by Nora.~Коробку открыла Нора.|A cyclist rang the bell.~Велосипедист позвонил в звонок.|The chef sliced the bread.~Повар нарезал хлеб.|Someone deliberately moved the chair.~Кто-то намеренно передвинул стул.|The volunteers cleaned the beach.~Волонтёры убрали пляж.');
add('Patient','Пациенс / объект воздействия','A patient undergoes a change or is affected by an event. It is not defined simply as whatever follows the verb.','Пациенс испытывает изменение или воздействие события. Его нельзя определить просто как слово после глагола.',
  'Identify the entity affected, damaged, transformed or otherwise changed. A patient can be an active object or passive subject.','Определите, что подвергается воздействию, повреждению или изменению. Пациенс бывает дополнением актива и подлежащим пассива.',...roleContrast,
  'The cup broke.~Чашка разбилась.|Maya broke the cup.~Майя разбила чашку.|The cup was broken.~Чашку разбили.|They repaired the roof.~Они починили крышу.|The ice melted.~Лёд растаял.|He painted the fence.~Он покрасил забор.');
add('Theme','Тема / перемещаемый участник','A theme is an entity located, moved, transferred or talked about in an event. Some analyses use theme more broadly than others.','Тема — участник, который находится где-либо, перемещается, передаётся или рассматривается в ситуации. В разных описаниях объём роли различается.',
  'Ask what is moved, located or transferred. Distinguish this semantic role from topic, the subject matter of a discourse.','Спросите, что перемещается, находится или передаётся. Отличайте эту роль от topic — темы дискурса.',...roleContrast,
  'She carried a suitcase.~Она несла чемодан.|The parcel arrived.~Посылка прибыла.|I put the keys on the shelf.~Я положил ключи на полку.|The painting hangs upstairs.~Картина висит наверху.|He sent the document to me.~Он отправил мне документ.|A leaf drifted downstream.~Лист плыл вниз по течению.');
add('Experiencer','Экспериенцер / носитель переживания','An experiencer perceives, feels or mentally experiences a situation. It need not control the experience.','Экспериенцер воспринимает, чувствует или переживает ситуацию. Он не обязательно контролирует это состояние.',
  'Typical predicates concern perception, emotion and cognition. The experiencer may be a subject or object.','Типичные предикаты обозначают восприятие, эмоции и мышление. Экспериенцер бывает подлежащим или дополнением.',...roleContrast,
  'I heard a noise.~Я услышал шум.|She loves jazz.~Она любит джаз.|The noise frightened the baby.~Шум испугал малыша.|He noticed the change.~Он заметил перемену.|This puzzle confuses me.~Эта головоломка меня озадачивает.|We remember that summer.~Мы помним то лето.');
add('Beneficiary','Бенефициант / выгодополучатель','A beneficiary is the participant for whose benefit an action is performed. This is not always the same as the physical recipient.','Бенефициант — участник, в чьих интересах выполняется действие. Он не всегда совпадает с физическим получателем.',
  'A for-phrase often marks a beneficiary. Some double-object constructions also have a beneficiary interpretation.','Группа с for часто обозначает бенефицианта. В некоторых конструкциях с двумя дополнениями также есть такое значение.',...roleContrast,
  'I baked a cake for Dad.~Я испёк торт для папы.|She saved me a seat.~Она заняла для меня место.|We raised money for the shelter.~Мы собрали деньги для приюта.|He cooked his guests dinner.~Он приготовил гостям ужин.|They built a ramp for wheelchair users.~Они построили пандус для пользователей колясок.|I kept a copy for you.~Я сохранил для тебя копию.');
add('Instrument','Инструмент / средство','An instrument is the means used to perform an action. It differs from the intentional participant using it.','Инструмент — средство выполнения действия. Он отличается от намеренно действующего участника, который им пользуется.',
  'With often introduces an instrument; by can describe a method. Context determines whether a noun phrase is a tool or an independent agent.','With часто вводит инструмент; by может обозначать способ. Контекст определяет, является ли предмет орудием или самостоятельным деятелем.',...roleContrast,
  'She cut the string with scissors.~Она разрезала верёвку ножницами.|He opened it with a key.~Он открыл это ключом.|We measured it with a ruler.~Мы измерили это линейкой.|I wrote the note with a pencil.~Я написал записку карандашом.|They lifted the load with a crane.~Они подняли груз краном.|She cleaned the lens with a cloth.~Она протёрла объектив тканью.');
add('Topic','Тема высказывания','A topic is what an utterance is about in its discourse context. It may already be established or explicitly introduced.','Тема — то, о чём говорится в данном дискурсивном контексте. Она может быть уже известной или вводиться явно.',
  'Topic expressions may appear early, or be introduced with as for. Topic does not automatically equal grammatical subject.','Тематическое выражение может стоять в начале или вводиться as for. Тема не обязательно совпадает с грамматическим подлежащим.',
  'Semantic theme and discourse topic are different notions despite similar translations. Context is necessary to identify a topic reliably.','Семантическая роль theme и дискурсивная topic различаются, несмотря на сходство переводов. Для надёжного определения нужен контекст.',
  'As for the tickets, I have booked them.~Что касается билетов, я их забронировал.|This garden, we planted ourselves.~Этот сад мы посадили сами.|About your proposal, I agree.~Насчёт твоего предложения: я согласен.|The new library opens tomorrow.~Новая библиотека открывается завтра.|Our neighbours have a dog. It is very quiet.~У наших соседей есть собака. Она очень тихая.|That question is difficult to answer.~На этот вопрос трудно ответить.');
add('Focus','Фокус высказывания','Focus identifies the most relevant or contrastive information for the current question or alternatives in a discourse.','Фокус выделяет наиболее значимую или противопоставленную информацию относительно текущего вопроса или альтернатив.',
  'Stress, word order and cleft constructions can mark focus. Changing focus can change the implied contrast without changing the basic event.','Фокус выражается ударением, порядком слов и расщеплёнными конструкциями. Его смена меняет подразумеваемое противопоставление без изменения самого события.',
  'Capital letters in examples indicate stress, not required spelling. Focus is not simply the last word in every sentence.','Прописные буквы в примерах обозначают ударение, а не обязательное написание. Фокус не всегда является последним словом.',
  'LENA bought the tickets, not Max.~Билеты купила ЛЕНА, а не Макс.|Lena bought the TICKETS, not the snacks.~Лена купила БИЛЕТЫ, а не закуски.|It was Lena who called.~Позвонила именно Лена.|What I need is a REST.~Мне нужен именно ОТДЫХ.|I ordered TEA, not coffee.~Я заказал ЧАЙ, а не кофе.|Only TOM knew the address.~Только ТОМ знал адрес.');
add('Given / New Information','Данная и новая информация','Given information is treated as accessible in context; new information updates the listener’s knowledge. Accessibility can come from discourse or a shared situation.','Данная информация считается доступной из контекста, новая обновляет знания слушателя. Доступность возникает из речи или общей ситуации.',
  'A/an often introduces a new countable referent; the or a pronoun can refer back. This is a tendency, not a complete rule for article choice.','A/an часто вводит новый исчисляемый объект; the или местоимение могут отсылать назад. Это тенденция, а не полное правило выбора артикля.',
  'New is a discourse property, not a synonym for indefinite. A definite expression may introduce information new to the conversation.','Новизна — свойство дискурса, а не синоним неопределённости. Определённая группа может вводить новую для разговора информацию.',
  'I saw a fox. The fox ran away.~Я увидел лису. Лиса убежала.|A visitor arrived. She brought flowers.~Пришла посетительница. Она принесла цветы.|We rented a flat. Its kitchen is tiny.~Мы сняли квартиру. Кухня в ней крошечная.|Close the door, please.~Закрой дверь, пожалуйста.|My cousin has just arrived.~Мой двоюродный брат только что приехал.|There is a problem with the printer.~С принтером возникла проблема.');
add('Discourse Marker','Дискурсивный маркер','A discourse marker helps manage a conversation or show how a contribution relates to surrounding discourse.','Дискурсивный маркер помогает организовать разговор или показать связь реплики с окружающим контекстом.',
  'Markers can signal transitions, reformulation, contrast, conclusions or hesitation. Their position and formality differ.','Маркеры обозначают переход, переформулирование, противопоставление, вывод или заминку. Их позиция и стиль различаются.',
  'A word can have another function elsewhere: well can describe how something is done. Do not add formal markers mechanically to every sentence.','То же слово может иметь другую функцию: well может обозначать качество действия. Не добавляйте формальные маркеры механически в каждое предложение.',
  'Well, I am not sure.~Ну, я не уверен.|Anyway, let us continue.~В любом случае давайте продолжим.|In other words, we need more time.~Иными словами, нам нужно больше времени.|However, there is another option.~Однако есть другой вариант.|By the way, Anna called.~Кстати, Анна звонила.|So, what happens next?~Итак, что происходит дальше?');
const theoryWarning=['This is a theory-dependent analysis in generative syntax, not a universal school-grammar label. Other frameworks may analyse the same words differently.','Это теоретический анализ генеративного синтаксиса, а не универсальная школьная категория. Другие подходы могут иначе описывать те же слова.'];
add('Determiner Phrase (DP)','Группа определителя (DP)','Under the DP hypothesis, a nominal expression is headed by a determiner rather than directly by a noun. D can be pronounced or structurally silent.','Согласно гипотезе DP, номинальная группа возглавляется определителем, а не непосредственно существительным. D может быть выражен или структурно не выражен.',
  'A simplified representation is [DP the [NP old book]]. D contributes reference or definiteness; the NP supplies descriptive content.','Упрощённая схема: [DP the [NP old book]]. D участвует в референции и определённости, NP задаёт описательное содержание.',...theoryWarning,
  'The old book fell.~Старая книга упала.|These two books are mine.~Эти две книги мои.|A visitor is waiting.~Ждёт посетитель.|My new bicycle is outside.~Мой новый велосипед снаружи.|Every student received a copy.~Каждый ученик получил экземпляр.|Some fresh bread is left.~Осталось немного свежего хлеба.');
add('Tense Phrase (TP)','Группа времени (TP)','In many generative analyses, TP is a clause-level projection headed by T, associated with tense and related finite-clause properties.','Во многих генеративных анализах TP является проекцией уровня предложения с главным компонентом T, связанным со временем и свойствами личной конструкции.',
  'A simplified outline is [TP subject [T ...] [VP ...]]. T may be realised through an auxiliary or verb morphology, depending on the analysis.','Упрощённая схема: [TP подлежащее [T ...] [VP ...]]. T может реализоваться вспомогательным глаголом или глагольной морфологией в зависимости от анализа.',...theoryWarning,
  'She walks to work.~Она ходит на работу пешком.|She walked home.~Она пошла домой пешком.|They will arrive soon.~Они скоро приедут.|He has finished the report.~Он закончил отчёт.|The children are sleeping.~Дети спят.|We did not agree.~Мы не согласились.');
add('Complementizer Phrase (CP)','Группа комплементатора (CP)','In many generative analyses, CP is a clause-level projection above TP. Its head C is associated with clause type or subordination.','Во многих генеративных анализах CP располагается над TP. Главный компонент C связан с типом предложения или подчинением.',
  'A simplified outline is [CP that [TP she left]]. Complementizers include that, whether and if in relevant uses; some C positions are unpronounced.','Упрощённая схема: [CP that [TP she left]]. В соответствующих употреблениях комплементаторы включают that, whether и if; некоторые позиции C не выражены.',...theoryWarning,
  'I believe that she left.~Я думаю, что она ушла.|We wonder whether he agreed.~Мы хотим знать, согласился ли он.|Ask if the shop is open.~Спроси, открыт ли магазин.|They said that the road was closed.~Они сказали, что дорога закрыта.|I do not know what she bought.~Я не знаю, что она купила.|Which book did you choose?~Какую книгу ты выбрал?');
